add_filter( 'woocommerce_checkout_cart_item_quantity', 'perfectpixel_checkout_quantity_input', 10, 3 );
add_action( 'woocommerce_checkout_update_order_review', 'perfectpixel_checkout_quantity_update' );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_checkout_quantity_script' );

function perfectpixel_checkout_quantity_input( $quantity_html, $cart_item, $cart_item_key ) {
	$product = $cart_item['data'];
	if ( ! $product || $product->is_sold_individually() ) {
		return $quantity_html;
	}
	return woocommerce_quantity_input(
		array(
			'input_name'  => 'perfectpixel_qty[' . $cart_item_key . ']',
			'input_value' => $cart_item['quantity'],
			'min_value'   => 0,
			'max_value'   => $product->get_max_purchase_quantity(),
		),
		$product,
		false
	);
}

function perfectpixel_checkout_quantity_update( $posted ) {
	parse_str( (string) $posted, $data );
	if ( empty( $data['perfectpixel_qty'] ) || ! is_array( $data['perfectpixel_qty'] ) ) {
		return;
	}
	foreach ( $data['perfectpixel_qty'] as $key => $qty ) {
		$key = sanitize_text_field( $key );
		$qty = max( 0, (int) $qty );
		$item = WC()->cart->get_cart_item( $key );
		if ( $item && (int) $item['quantity'] !== $qty ) {
			WC()->cart->set_quantity( $key, $qty, false );
		}
	}
	WC()->cart->calculate_totals();
}

function perfectpixel_checkout_quantity_script() {
	?>
	<script>
	jQuery( function ( $ ) {
		var timer;
		$( 'form.checkout' ).on( 'change', 'input[name^="perfectpixel_qty"]', function () {
			clearTimeout( timer );
			timer = setTimeout( function () {
				$( document.body ).trigger( 'update_checkout' );
			}, 400 );
		} );
	} );
	</script>
	<?php
}
